css:
@font-face {
  font-family: 'Salinas';
  src: url('/files/SalinasDemo-Regular.otf') format('woff');
}

* {
  font-size:14px;
  font-family: 'Salinas', Monospace;
}

.head-address{
    font-size: 10px;
    width: 270px;
}

hr {
    border-top: 1px solid white !important
}

#header-html .print-heading{
    border-bottom: 1px solid white;
}

.print-format th{
    background-color: #ffffff !important;
    color: black;
}

table tr td, table tr th {
    border: 1.7px solid #6e6e6e !important;
}

.total-row {
    border: none !important;
}
.total-row th {
    text-align: right !important;
    border: none !important;
}

.total-row td {
    font-weight: bold;
    border: 1.7px solid #6e6e6e;
}
td .value small{
    font-size: .8em;
}

.footerinfo {
    background: #6D6D6D;
    color: white;
    font-size: 10px;
}
